cd $TMPDIR/scripts && python3 -I - <<'EOF'
import json,re
rows=json.load(open("scored3.json"))
UTIL=["centerpoint","northern indiana public service","nipsco","citizens gas","citizens energy","vectren","indiana american water","ohio valley gas","american electric power","duke energy","community natural gas","midwest natural gas","frontier communications"]
def is_util(r):
    s=re.sub(r'^\s+','',r or '').lower()
    return any(s.startswith(u) for u in UTIL)
def headline(block):
    b=block.replace('$$','$')
    m=re.search(r'\$\s*(\d{1,3}(?:,\s*\d{3})+|\d+)',b)
    return (int(re.sub(r'[,\s]','',m.group(1))) if m else 0)
for r in rows:
    r['util']=is_util(r['resp']); r['head']=headline(r['pen'])
json.dump(rows,open("final.json","w"),indent=1)
for yr in [2021,2025]:
    rs=[r for r in rows if r['year']==yr]
    nu=[r for r in rs if not r['util']]
    tot=sum(r['head'] for r in nu)
    print(yr,"cases",len(rs),"nonutil",len(nu),"sum",tot,"mean",round(tot/len(nu),4),"zeros",sum(r['head']==0 for r in nu))
